## Approach

For a given $N$, I want a modulus $M$ and a base $A$ whose multiplicative order mod $M$ is exactly $N$.

**Idea:** find a prime $p \equiv 1 \pmod N$. Then the group $(\mathbb{Z}/p)^*$ is cyclic of order $p-1$, which is divisible by $N$, so it contains an element of order exactly $N$.

Concretely:
1. Search $p = 2tN+1$ for $t=1,2,3,\dots$ until $p$ is prime (Miller–Rabin, deterministic bases for 64‑bit). Since $N\le 10^9$ and $t$ stays tiny, $p \ll 10^{18}$.
2. Factor $N$ by trial division with a sieve of primes up to $\sqrt{10^9}\approx 31623$.
3. Try $x = 2,3,4,\dots$, set $A = x^{(p-1)/N} = x^{2t} \bmod p$. Then $\operatorname{ord}(A)\mid N$, and it equals $N$ iff $A^{N/q}\not\equiv 1$ for every prime $q\mid N$. A random/small $x$ works with probability $\varphi(N)/N$, so only a couple of tries are needed.
4. Output `A p`. Special case $N=1$: output `1 1`.

Results are memoized for repeated $N$.

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long u64; typedef __uint128_t u128;

static inline u64 mulmod(u64 a,u64 b,u64 m){return (u128)a*b%m;}
static u64 powmod(u64 a,u64 e,u64 m){u64 r=1;a%=m;while(e){if(e&1)r=mulmod(r,a,m);a=mulmod(a,a,m);e>>=1;}return r;}
static bool isprime(u64 n){
    if(n<2)return false;
    for(u64 p:{2ULL,3ULL,5ULL,7ULL,11ULL,13ULL,17ULL,19ULL,23ULL,29ULL,31ULL,37ULL}){if(n%p==0)return n==p;}
    u64 d=n-1;int s=0;while(!(d&1)){d>>=1;s++;}
    for(u64 a:{2ULL,325ULL,9375ULL,28178ULL,450775ULL,9780504ULL,1795265022ULL}){
        u64 x=powmod(a%n,d,n);
        if(x<=1||x==n-1)continue;
        bool comp=true;
        for(int i=1;i<s;i++){x=mulmod(x,x,n);if(x==n-1){comp=false;break;}}
        if(comp)return false;
    }
    return true;
}
int main(){
    const int LIM=31623;
    vector<int> primes; vector<char> comp(LIM+1,0);
    for(int i=2;i<=LIM;i++){if(!comp[i]){primes.push_back(i);for(long long j=(long long)i*i;j<=LIM;j+=i)comp[j]=1;}}
    int T; if(scanf("%d",&T)!=1)return 0;
    unordered_map<long long,pair<u64,u64>> memo; memo.reserve(20000);
    string out;
    while(T--){
        long long N; scanf("%lld",&N);
        auto it=memo.find(N);
        if(it!=memo.end()){out+=to_string(it->second.first);out+=' ';out+=to_string(it->second.second);out+='\n';continue;}
        if(N==1){memo[N]={1,1};out+="1 1\n";continue;}
        // factor N
        vector<long long> qs; long long tmp=N;
        for(int pr:primes){ if((long long)pr*pr>tmp)break; if(tmp%pr==0){qs.push_back(pr);while(tmp%pr==0)tmp/=pr;} }
        if(tmp>1)qs.push_back(tmp);
        // find prime p = 2tN+1
        u64 p=0,t=0;
        for(u64 tt=1;;tt++){
            u64 cand=2ULL*tt*(u64)N+1ULL;
            bool ok=true;
            for(int i=0;i<100 && i<(int)primes.size();i++){u64 pr=primes[i]; if(cand%pr==0){ok=(cand==pr);break;}}
            if(!ok)continue;
            if(isprime(cand)){p=cand;t=tt;break;}
        }
        u64 A=0;
        for(u64 x=2;;x++){
            u64 cand=powmod(x%p,2ULL*t,p);
            if(cand<=1)continue;
            bool good=true;
            for(long long q:qs){ if(powmod(cand,(u64)(N/q),p)==1){good=false;break;} }
            if(good){A=cand;break;}
        }
        memo[N]={A,p};
        out+=to_string(A);out+=' ';out+=to_string(p);out+='\n';
    }
    fwrite(out.data(),1,out.size(),stdout);
    return 0;
}
```

