import sys

def count(N):
    if N < 10:
        return 0
    s = str(N)
    L = len(s)
    total = 0
    for d in range(2, L):
        for a in range(1, 10):
            total += a ** (d - 1)
    a0 = int(s[0])
    for a in range(1, a0):
        total += a ** (L - 1)
    # tight case: first digit == a0
    a = a0
    tight = True
    for i in range(1, L):
        di = int(s[i])
        m = min(a, di)
        if m > 0:
            total += m * (a ** (L - 1 - i))
        if di < a:
            continue
        else:
            tight = False
            break
    if tight:
        total += 1
    return total

