import sys
from functools import lru_cache

def count_snake(N: int) -> int:
    if N < 10:
        return 0
    s = str(N)
    digits = list(map(int, s))
    n = len(digits)

    @lru_cache(maxsize=None)
    def dfs(i: int, tight: bool, started: bool, tail: bool, top: int) -> int:
        if i == n:
            return 1 if started and tail else 0
        limit = digits[i] if tight else 9
        total = 0
        if not started:
            for x in range(0, limit + 1):
                ntight = tight and (x == limit)
                if x == 0:
                    total += dfs(i + 1, ntight, False, False, 0)
                else:
                    total += dfs(i + 1, ntight, True, False, x)
        else:
            max_x = min(limit, top - 1)
            if max_x >= 0:
                for x in range(0, max_x + 1):
                    ntight = tight and (x == limit)
                    total += dfs(i + 1, ntight, True, True, top)
        return total

    return dfs(0, True, False, False, 0)

def main():
    data = sys.stdin.read().strip().split()
    L = int(data[0])
    R = int(data[1])
    ans = count_snake(R) - count_snake(L - 1)
    print(ans)

if __name__ == "__main__":
    main()
