Solution idea:
- The graph defined by P is a functional graph: each component is a directed cycle with trees feeding into the cycle nodes.
- Along each edge i → P_i, the constraint is y_i ≤ y_{P_i}. Hence, values along a cycle must all be equal. For a fixed value c on a cycle, every attached tree must be labeled with values in [1..c] nondecreasing toward the cycle.
- For a rooted tree with parent ≥ children, if F_v(k) is the number of valid labelings of the subtree at v with y_v ≤ k, then:
  - For a leaf: F_v(k) = k.
  - For general v with children u: F_v(k) = sum_{x=1..k} ∏_u F_u(x).
  - The number of labelings with y_v exactly k is E_v(k) = F_v(k) − F_v(k−1) = ∏_u F_u(k).
- For a cycle C, all its nodes must take the same value c, so the number of labelings for the component is S_C = sum_{c=1..M} ∏_{v∈C} E_v(c).
- The final answer is the product over cycles of S_C, modulo 998244353.

We can compute arrays F_v(1..M) for all non-cycle nodes bottom-up (from leaves to the cycle) and E_v(1..M) = ∏ F_child(·) for cycle nodes. Then for each cycle, combine E_v arrays.

This runs in O(N·M) time and uses O(N·M) memory, which fits the given constraints.

Code (C++17):

```cpp
#include <bits/stdc++.h>
using namespace std;

static const int MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if (!(cin >> N >> M)) return 0;
    vector<int> P(N + 1);
    for (int i = 1; i <= N; ++i) cin >> P[i];

    // Find cycle nodes via Kahn's algorithm on functional graph
    vector<int> indeg(N + 1, 0);
    for (int i = 1; i <= N; ++i) indeg[P[i]]++;
    queue<int> q;
    vector<char> is_cycle(N + 1, true);
    for (int i = 1; i <= N; ++i) if (indeg[i] == 0) q.push(i);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        is_cycle[v] = false;
        int p = P[v];
        if (--indeg[p] == 0) q.push(p);
    }

    // Build lists of non-cycle children
    vector<vector<int>> children(N + 1);
    vector<int> deg_tree(N + 1, 0);
    for (int u = 1; u <= N; ++u) {
        if (!is_cycle[u]) {
            int v = P[u];
            children[v].push_back(u);
            deg_tree[v]++;
        }
    }

    // For each node v, prod[v][k] will hold:
    // - for non-cycle nodes during DP: product over F_child(k), then overwritten by F_v(k) (prefix sum)
    // - for cycle nodes after DP: E_v(k) = product over F_child(k) (non-cycle children only)
    vector<vector<int>> prod(N + 1, vector<int>(M + 1, 1));

    // Process non-cycle nodes bottom-up
    queue<int> leaves;
    vector<int> need(N + 1, 0);
    for (int v = 1; v <= N; ++v) {
        need[v] = (int)children[v].size(); // number of non-cycle children
    }
    for (int v = 1; v <= N; ++v) {
        if (!is_cycle[v] && need[v] == 0) leaves.push(v);
    }

    while (!leaves.empty()) {
        int v = leaves.front(); leaves.pop();

        // Compute F_v as prefix sums of current prod[v]
        long long acc = 0;
        for (int k = 1; k <= M; ++k) {
            acc += prod[v][k];
            if (acc >= MOD) acc -= MOD;
            prod[v][k] = (int)acc; // now prod[v] is F_v
        }

        int p = P[v];
        // Multiply F_v into parent's product array (parent may be cycle or non-cycle)
        for (int k = 1; k <= M; ++k) {
            prod[p][k] = int((1LL * prod[p][k] * prod[v][k]) % MOD);
        }
        // Decrease remaining non-cycle children count of parent; if parent is non-cycle and ready, push it
        if (!is_cycle[p]) {
            if (--need[p] == 0) leaves.push(p);
        }
    }

    // Now for each cycle, combine E_v (which are prod[v] for cycle nodes) and sum over k
    vector<char> seen(N + 1, false);
    long long ans = 1;
    for (int i = 1; i <= N; ++i) {
        if (is_cycle[i] && !seen[i]) {
            // extract the cycle
            vector<int> cyc;
            int v = i;
            do {
                cyc.push_back(v);
                seen[v] = true;
                v = P[v];
            } while (v != i);

            // t[k] = product over v in cycle of E_v(k)
            vector<int> t(M + 1, 1);
            for (int vtx : cyc) {
                for (int k = 1; k <= M; ++k) {
                    t[k] = int((1LL * t[k] * prod[vtx][k]) % MOD);
                }
            }
            long long S = 0;
            for (int k = 1; k <= M; ++k) {
                S += t[k];
                if (S >= MOD) S -= MOD;
            }
            ans = (ans * S) % MOD;
        }
    }

    cout << ans % MOD << '\n';
    return 0;
}
```

Explanation of main steps:
- Identify cycle nodes using Kahn’s algorithm on the functional graph.
- For each non-cycle node v, compute F_v(k) bottom-up:
  - Maintain for every node a product array over k=1..M accumulating contributions from its (non-cycle) children.
  - When all children of v are processed, take prefix sums over k to get F_v(k).
  - Multiply F_v into the parent’s product array.
- For each cycle, after trees are processed, each cycle node v has E_v(k) equal to its product array. Multiply E_v(k) around the cycle, sum over k=1..M, and multiply contributions of all cycles.

All arithmetic is modulo 998244353.

