    const int BITS = 31; // enough for Z up to 1e9
    vector<long long> val(N, 0), ans(N, 0);
    vector<int> comp(N, -1);
    int comp_id = 0;

    for (int s = 0; s < N; ++s) {
        if (comp[s] != -1) continue;
        // BFS/DFS to assign values and check consistency
        vector<int> st;
        vector<int> nodes;
        st.push_back(s);
