        val[s] = 0;

        bool ok = true;
        while (!st.empty() && ok) {
            int u = st.back(); st.pop_back();
            nodes.push_back(u);
            for (auto [v, z] : adj[u]) {
                if (comp[v] == -1) {
                    comp[v] = comp_id;
                    val[v] = val[u] ^ z;
                    st.push_back(v);
