                    if ( (val[u] ^ val[v]) != z ) {
                        ok = false;
                        break;
                    }
                }
            }
        }
        if (!ok) {
            cout << -1 << '\n';
            return 0;
        }

        // Choose optimal constant C for this component to minimize sum
        long long C = 0;
        int sz = (int)nodes.size();
        for (int b = 0; b < BITS; ++b) {
            int ones = 0;
            for (int u : nodes) {
                if ((val[u] >> b) & 1LL) ++ones;
            }
            if (ones > sz - ones) C |= (1LL << b);
        }
        for (int u : nodes) ans[u] = val[u] ^ C;

        ++comp_id;
    }

    for (int i = 0; i < N; ++i) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
