Solution idea:
For any subarray, let A be the set of distinct values appearing in it. You can remove, in one step, any interval [a, b] such that every value a..b appears at least once. Therefore, the minimum number of steps equals the number of connected components (value-runs) of A on the integer line. This equals:
g(L, R) = (#distinct values in [L, R]) − (#adjacent pairs v, v+1 both present in [L, R]).

Hence, the required sum is:
sum over subarrays of distinct count − sum over subarrays of adjacent-present count.

We can compute:
- Sum of distinct counts: For each value v, count subarrays that contain v at least once. This equals T − sum over gaps without v of C(len+1, 2), where T = N(N+1)/2.
- Sum of adjacent-present counts: For each pair (t, t+1), count subarrays that contain both. Using inclusion-exclusion:
  both(t, t+1) = T − no_t − no_{t+1} + no_{t or t+1},
where no_{t or t+1} is computed from gaps of the merged positions of t and t+1. Summing this over t=1..N−1 gives the total.

The total complexity is O(N): each occurrence participates in at most two merges.

Code (C++17):

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    if (!(cin >> N)) return 0;
    vector<int> X(N + 1);
    for (int i = 1; i <= N; ++i) cin >> X[i];

    vector<vector<int>> pos(N + 2);
    for (int i = 1; i <= N; ++i) pos[X[i]].push_back(i);

    auto choose2 = [](long long L) -> long long { return L * (L + 1) / 2; };
    long long T = choose2((long long)N);

    // no1[v] = number of subarrays containing no occurrence of value v
    vector<long long> no1(N + 2, 0);
    for (int v = 1; v <= N; ++v) {
        long long sum = 0;
        int prev = 0;
        for (int p : pos[v]) {
            long long L = (long long)p - prev - 1;
            sum += choose2(L);
            prev = p;
        }
        long long L = (long long)N - prev;
        sum += choose2(L);
        no1[v] = sum;
    }

    long long sumDistinct = 0;
    for (int v = 1; v <= N; ++v) {
        sumDistinct += T - no1[v];
    }

    long long sumEdges = 0;
    for (int t = 1; t <= N - 1; ++t) {
        // compute no_{t or t+1} via merging positions
        const auto &A = pos[t];
        const auto &B = pos[t + 1];
        int i = 0, j = 0, prev = 0;
        long long noUnion = 0;
        while (i < (int)A.size() || j < (int)B.size()) {
            int m;
            if (j == (int)B.size() || (i < (int)A.size() && A[i] < B[j])) {
                m = A[i++];
            } else {
                m = B[j++];
            }
            long long L = (long long)m - prev - 1;
            noUnion += choose2(L);
            prev = m;
        }
        long long L = (long long)N - prev;
        noUnion += choose2(L);

        long long both = T - no1[t] - no1[t + 1] + noUnion;
        sumEdges += both;
    }

    long long ans = sumDistinct - sumEdges;
    cout << ans << '\n';
    return 0;
}
