import sys
from functools import lru_cache

def count_crest_upto(N: int) -> int:
    if N < 10:
        return 0
    digits = list(map(int, str(N)))
    m = len(digits)

    @lru_cache(maxsize=None)
    def dp(pos: int, started: bool, tight: bool, d0: int, length: int) -> int:
        if pos == m:
            return 1 if started and length >= 2 else 0

        up = digits[pos] if tight else 9
        res = 0

        if not started:
            # Place 0 (still not started)
            res += dp(pos + 1, False, tight and (0 == up), 0, 0)
            # Start the number with first non-zero digit
            for x in range(1, up + 1):
                res += dp(pos + 1, True, tight and (x == up), x, 1)
        else:
            # After starting, all digits must be < d0
            hi = min(up, d0 - 1)
            if hi >= 0:
                for x in range(0, hi + 1):
                    res += dp(pos + 1, True, tight and (x == up), d0, length + 1)

        return res

    return dp(0, False, True, 0, 0)

def main():
    data = sys.stdin.read().strip().split()
    L = int(data[0])
    R = int(data[1])
    ans = count_crest_upto(R) - count_crest_upto(L - 1)
    print(ans)

if __name__ == "__main__":
    main()
