```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if (!(cin >> N >> M)) return 0;
    vector<int> X(M), Y(M);
    vector<long long> Z(M);
    for (int i = 0; i < M; ++i) {
        int xi, yi;
        long long zi;
        cin >> xi >> yi >> zi;
        X[i] = xi - 1;
        Y[i] = yi - 1;
        Z[i] = zi;
    }

    // Build static graph
    vector<vector<pair<int,int>>> adj(N);
    for (int i = 0; i < M; ++i) {
        int u = X[i], v = Y[i];
        adj[u].push_back({v, i});
        adj[v].push_back({u, i});
    }

    vector<long long> B(N, 0);
    const int MAXB = 30; // 0..29 since Z_i <= 1e9

    for (int k = 0; k < MAXB; ++k) {
        vector<int> val(N, -1);
        for (int s = 0; s < N; ++s) {
            if (val[s] != -1) continue;

            // Explore component containing s
            vector<int> comp;
            comp.push_back(s);
            val[s] = 0;
            size_t idx = 0;
            while (idx < comp.size()) {
                int u = comp[idx++];
                for (auto &edge : adj[u]) {
                    int v = edge.first;
                    int ei = edge.second;
                    int w = (int)((Z[ei] >> k) & 1LL);
                    if (val[v] == -1) {
                        val[v] = val[u] ^ w;
                        comp.push_back(v);
                    } else {
                        if (val[v] != (val[u] ^ w)) {
                            cout << -1 << "\n";
                            return 0;
                        }
                    }
                }
            }

            // Decide whether to flip this component
            int cnt1 = 0;
            for (int node : comp) if (val[node] == 1) cnt1++;
            int sz = (int)comp.size();
            bool flip = (cnt1 > sz - cnt1);
            for (int node : comp) {
                int bit = val[node];
                if (flip) bit = 1 - bit;
                if (bit) B[node] |= (1LL << k);
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        if (i) cout << ' ';
        cout << B[i];
    }
    cout << "\n";
    return 0;
}
```

