use std::io::{self, Read};

fn isqrt(n: u128) -> u128 {
    // integer sqrt of n
    let mut lo: u128 = 0;
    let mut hi: u128 = n;
    let mut res: u128 = 0;
    while lo <= hi {
        let mid = (lo + hi) >> 1;
        if mid == 0 {
            lo = 1;
            continue;
        }
        if mid <= n / mid {
            res = mid;
            lo = mid + 1;
        } else {
            if mid == 0 { break; }
            hi = mid - 1;
        }
    }
    res
}

fn main() {
    // Read N
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let n: u128 = input.trim().parse().unwrap();

    let mut ans: u128 = 0;
    let mut pow2: u128 = 2; // start with a = 1
    while pow2 <= n {
        let m = n / pow2;
        let s = isqrt(m);
        ans += (s + 1) / 2; // number of odd t with t^2 <= m
        pow2 <<= 1;
    }

    println!("{}", ans);
}
